/**
 * Places an issue under a parent of the same project, or makes it a root
 * again. Its sub-issues move with it, so depth is judged by the deepest one.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    const parent = await requireParent(
      input.orgId,
      issue.projectId,
      input.parentId,
    );
    const all = await issueRepo.listProjectIssues(input.orgId, issue.projectId);
    const byId = indexById(all);
    const below = descendantsOf(issue.id, childrenIndex(all));
    if (parent.id === issue.id || below.some((d) => d.id === parent.id)) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    const height = Math.max(
      0,
      ...below.map((d) => levelOf(d, byId) - levelOf(issue, byId)),
    );
    if (levelOf(parent, byId) + 1 + height > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    issue.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct, live sub-issues, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const all = await issueRepo.listProjectIssues(orgId, issue.projectId);
  return all
    .filter((child) => child.parentId === issue.id && child.archivedAt === null)
    .sort((a, b) =>
      a.createdAt < b.createdAt
        ? -1
        : a.createdAt > b.createdAt
          ? 1
          : a.number - b.number,
    );
}

/** Counts over every live issue below the issue, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const all = await issueRepo.listProjectIssues(orgId, issue.projectId);
  const live = descendantsOf(issue.id, childrenIndex(all)).filter(
    (d) => d.archivedAt === null,
  );
  const closed = live.filter((d) => isClosedStatus(d.status)).length;
  return { total: live.length, open: live.length - closed, closed };
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** A parent must be a live issue of the same project in the same workspace. */
async function requireParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

function indexById(all: readonly Issue[]): ReadonlyMap<string, Issue> {
  return new Map(all.map((issue) => [issue.id, issue]));
}

function childrenIndex(
  all: readonly Issue[],
): ReadonlyMap<string, readonly Issue[]> {
  const map = new Map<string, Issue[]>();
  for (const issue of all) {
    if (issue.parentId === null) continue;
    const list = map.get(issue.parentId) ?? [];
    list.push(issue);
    map.set(issue.parentId, list);
  }
  return map;
}

/** Every issue below `rootId`, at any depth, archived ones included. */
function descendantsOf(
  rootId: string,
  children: ReadonlyMap<string, readonly Issue[]>,
): readonly Issue[] {
  const seen = new Set<string>([rootId]);
  const out: Issue[] = [];
  const queue = [rootId];
  while (queue.length > 0) {
    const id = queue.shift() as string;
    for (const child of children.get(id) ?? []) {
      if (seen.has(child.id)) continue;
      seen.add(child.id);
      out.push(child);
      queue.push(child.id);
    }
  }
  return out;
}

/** Level in the tree: a root issue is at level 0. */
function levelOf(issue: Issue, byId: ReadonlyMap<string, Issue>): number {
  const seen = new Set<string>([issue.id]);
  let level = 0;
  let parentId = issue.parentId;
  while (parentId !== null && !seen.has(parentId)) {
    const parent = byId.get(parentId);
    if (!parent) break;
    seen.add(parentId);
    level += 1;
    parentId = parent.parentId;
  }
  return level;
}

/**
 * Tells the direct parent's assignee when the sub-issue that just stopped
 * being open was the last open one below it.
 */
async function notifySubIssuesCompleted(
  actor: Actor,
  closed: Issue,
): Promise<void> {
  if (closed.parentId === null) return;
  const parent = await issueRepo.findIssueById(closed.orgId, closed.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const all = await issueRepo.listProjectIssues(parent.orgId, parent.projectId);
  const stillOpen = descendantsOf(parent.id, childrenIndex(all)).some(
    (d) => d.archivedAt === null && !isClosedStatus(d.status),
  );
  if (stillOpen) return;

  await notify(parent.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are closed",
    body: `Every sub-issue of issue ${parent.id} is now closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
